import sys

def is_valid_parentheses(s: str) -> bool:
    stack = []
    mapping = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in mapping:
            if not stack:
                return False
            top = stack.pop()
            if mapping[char] != top:
                return False
        else:
            stack.append(char)

    return len(stack) == 0

if __name__ == '__main__':
    raw = sys.stdin.read().strip()
    print(is_valid_parentheses(raw))

